00028: async function req(u,o={}){
00029:   const r=await fetch(u,{cache:'no-store',...o}); let j={};
00030:   try{j=await r.json()}catch{}
00031:   if(!r.ok) throw Error(j.error||`${r.status} ${r.statusText}`);
00032:   return j;
00033: }
00034: 
00035: function updateState(){
00036:   const label=!state.active?'INACTIVE':state.muted?'MUTED':voiceBusy?'TRANSCRIBING':'LISTENING';
00037:   $('#activePill').textContent=label;
00038:   $('#activateBtn').textContent=state.active?'DEACTIVATE EIRA':'ACTIVATE EIRA';
00039:   $('#muteBtn').textContent=state.muted?'UNMUTE':'MUTE';
00040:   document.body.classList.toggle('listening',state.active&&!state.muted);
00041:   document.body.classList.toggle('muted',state.muted);
00042: }
