00062: async function submitText(text,source='text'){
00063:   const clean=String(text||'').trim(); if(!clean)return null;
00064:   add(source==='voice'?'You · voice':'You',clean,'me');
00065:   const j=await req('/v1/text',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({text:clean,source})});
