00070: async function acquireMic(){
00071:   if(mic&&mic.active)return mic;
00072:   if(!window.isSecureContext)throw Error('Microphone requires HTTPS on iPhone Safari');
00073:   mic=await navigator.mediaDevices.getUserMedia({audio:{echoCancellation:true,noiseSuppression:true,autoGainControl:true},video:false});
