00080: function packPCM16(frames,inputRate){
00081:   let total=frames.reduce((n,a)=>n+a.length,0),src=new Float32Array(total),o=0;
00082:   for(const a of frames){src.set(a,o);o+=a.length}
00083:   const ratio=inputRate/16000,outLen=Math.max(1,Math.floor(src.length/ratio)),buf=new ArrayBuffer(outLen*2),dv=new DataView(buf);
00084:   for(let i=0;i<outLen;i++){
00085:     const start=Math.floor(i*ratio),end=Math.max(start+1,Math.floor((i+1)*ratio)); let sum=0,n=0;
00086:     for(let j=start;j<end&&j<src.length;j++){sum+=src[j];n++}
00087:     const s=Math.max(-1,Math.min(1,n?sum/n:0)); dv.setInt16(i*2,s<0?s*32768:s*32767,true);
00088:   }
00089:   return buf;
00090: }
00091: 
00092: function beginUtterance(){
00093:   if(!mic||voiceBusy||state.muted||pcmNode)return;
00094:   pcmFrames=[]; const src=audioCtx.createMediaStreamSource(mic); pcmNode=audioCtx.createScriptProcessor(4096,1,1);
00095:   pcmNode.onaudioprocess=e=>pcmFrames.push(new Float32Array(e.inputBuffer.getChannelData(0)));
00096:   src.connect(pcmNode); pcmNode.connect(audioCtx.destination); recordStarted=performance.now(); silenceSince=0; document.body.classList.add('hearing');
00097: }
