00105:     const j=await req('/v1/listen?sample_rate=16000&channels=1&sample_width=2',{method:'POST',headers:{'Content-Type':'application/octet-stream'},body});
00106:     const transcript=String(j.utterance||j.text||'').trim(), r=j.result||j, answer=r.text||r.reply||r.response;

